502	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
503	// exit(200).
504	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
505	                                const char *path)
506	{
507	    struct hybrid_state_v1 s;
508	    drain_state_into(vcpu_idx, pc, &s);
509	    if (write_state_atomic(&s, path) != 0) {
510	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
511	        exit(2);
512	    }
513	    // LM transport (F1) + HVM transport (F2): content sidecars ride next to
514	    // the state file; this is the single choke point, so every trigger mode
515	    // (marker/pc/oracle) gets them.
516	    drain_lm_sidecar(path, ".ilm", ilm_base_arg, ilm_size_arg);
517	    drain_lm_sidecar(path, ".dlm", dlm_base_arg, dlm_size_arg);
518	    drain_lm_sidecar(path, ".hvm", hvm_base_arg, hvm_size_arg);
519	    if (log_level_arg <= 1) {
520	        fprintf(stderr,
521	                "[hybrid_handoff] drained state to %s (pc=%#" PRIx64
522	                ", flags=%#x, vlenb=%" PRIu64 ")\n",
523	                path, s.pc, s.flags, (uint64_t) s.vlenb);
524	    }
525	}
